<!--
  BitDepth — a black→white grayscale ramp quantized to the selected bit depth
  (2^bits levels). Low bit depth shows visible banding; high bit depth looks
  continuous. Wrapped in <Demo> by the slide so the slider doesn't reach reveal.
-->
<script lang="ts">
  let bits = $state(3);
  let canvasEl: HTMLCanvasElement;

  const levels = $derived(Math.pow(2, bits));

  function draw() {
    const ctx = canvasEl.getContext('2d');
    if (!ctx) return;
    const w = canvasEl.width;
    const img = ctx.createImageData(w, 1);
    const d = img.data;
    const n = Math.pow(2, bits);
    for (let x = 0; x < w; x++) {
      const p = x / (w - 1); // 0..1 across the bar
      // quantise to n discrete levels, mapped black (0) -> white (1)
      const v = n <= 1 ? 0 : Math.min(n - 1, Math.floor(p * n)) / (n - 1);
      const g = Math.round(v * 255);
      const j = x * 4;
      d[j] = g;
      d[j + 1] = g;
      d[j + 2] = g;
      d[j + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
  }

  $effect(() => {
    bits; // redraw whenever bit depth changes
    if (canvasEl) draw();
  });
</script>

<div class="wrap">
  <canvas
    bind:this={canvasEl}
    width="1024"
    height="1"
    class="bar"
    aria-label="Grayscale ramp from black to white, quantized to the selected bit depth"
  ></canvas>

  <div class="readout">
    <span><em>{bits}</em>-bit</span>
    <span>2<sup>{bits}</sup> = <em>{levels.toLocaleString()}</em> level{levels === 1 ? '' : 's'}</span>
  </div>

  <label class="control">
    <span>bit depth <em>{bits}</em></span>
    <input type="range" min="0" max="16" step="1" bind:value={bits} />
  </label>
</div>

