<!--
  SlideMenu — a contents drawer. A fixed toggle button opens a panel listing
  every slide (grouped by chapter); selecting one jumps the deck there. Reads
  the slide registry for titles and the shared deck state for the current slide.
-->
<script lang="ts">
  import { slides } from '../../slides';
  import { deck, goTo, toggleMenu } from '../deck.svelte';

  // Build ordered chapter groups once; each item keeps its registry index,
  // which equals reveal's horizontal slide index (the deck is flat).
  interface MenuItem {
    index: number;
    id: string;
    title: string;
  }
  interface Group {
    chapter: string;
    items: MenuItem[];
  }

  const groups: Group[] = (() => {
    const out: Group[] = [];
    slides.forEach((s, index) => {
      if (s.hideInMenu) return;
      const chapter = s.chapter ?? '';
      let g = out.at(-1);
      if (!g || g.chapter !== chapter) {
        g = { chapter, items: [] };
        out.push(g);
      }
      g.items.push({ index, id: s.id, title: s.title });
    });
    return out;
  })();
</script>

<button
  class="menu-toggle"
  type="button"
  aria-label={deck.menuOpen ? 'Close contents' : 'Open contents'}
  aria-expanded={deck.menuOpen}
  onclick={toggleMenu}
>
  <span class="bars" class:open={deck.menuOpen}>
    <span></span><span></span><span></span>
  </span>
  <span class="label">Contents</span>
</button>

{#if deck.menuOpen}
  <!-- backdrop -->
  <button class="scrim" aria-label="Close contents" onclick={toggleMenu}></button>
  <nav class="drawer" aria-label="Slide contents">
    <header class="drawer-head">
      <span class="kick">Astro Deep Dive</span>
      <h2>Contents</h2>
    </header>
    <ol class="toc">
      {#each groups as group, gi (gi)}
        {#if group.chapter}
          <li class="chapter">{group.chapter}</li>
        {/if}
        {#each group.items as item (item.id)}
          <li>
            <button
              class="toc-item"
              class:current={deck.index === item.index}
              type="button"
              onclick={() => goTo(item.index)}
            >
              <span class="num">{String(item.index + 1).padStart(2, '0')}</span>
              <span class="ttl">{item.title}</span>
            </button>
          </li>
        {/each}
      {/each}
    </ol>
  </nav>
{/if}

