<!--
  ExposureNoise — interactive shot-noise demo. white_pine.png is treated as a
  field of per-pixel photon *rates*; at exposure t each pixel collects
  n ~ Poisson(rate · gain · t). The frame shows the per-pixel *estimate*
  n / (gain · t): its mean is the scene itself (the idealized infinite-exposure
  average), while its relative noise shrinks as 1/sqrt(signal). So brightness
  stays roughly constant and the grain fades as the exposure runs out to a full
  two minutes. A highlighted pixel's Poisson distribution is charted live.

  NOTE (owner): the photon gain K and the exposure range are PLACEHOLDER
  calibration for feel, not a calibrated sensor model — tune to taste.
-->
<script lang="ts">
  import { onMount } from 'svelte';
  // Imported so Vite hashes it and resolves the Pages base path.
  import whitePine from '../../images/white_pine.webp';

  // --- simulation parameters (placeholder calibration) -------------------
  const W = 200; // internal sim resolution (kept small so per-pixel Poisson is cheap)
  const H = 132;
  const K = 6; // photons / second per unit scene intensity (gain) — placeholder
  const T_MAX = 120; // exposure slider max: a full two minutes

  let exposure = $state(4); // seconds — start short so the grain is obvious

  // Scene photon rates per channel + luminance, filled from the image on mount.
  let baseR = new Float32Array(0);
  let baseG = new Float32Array(0);
  let baseB = new Float32Array(0);
  let baseLum = new Float32Array(0);
  let ready = $state(false);

  const RWIN = 4; // half-size of the highlighted region: a (2·RWIN+1)² patch
  let hx = $state(W >> 1); // centre of the highlighted region
  let hy = $state(H >> 1);
  let hLum = $state(0.5); // mean luminance (photon rate) of that region

  let canvasEl: HTMLCanvasElement;

  // --- random sampling ---------------------------------------------------
  let spare: number | null = null;
  function gauss(): number {
    if (spare !== null) {
      const s = spare;
      spare = null;
      return s;
    }
    const u = Math.random() || 1e-9;
    const v = Math.random();
    const m = Math.sqrt(-2 * Math.log(u));
    spare = m * Math.sin(2 * Math.PI * v);
    return m * Math.cos(2 * Math.PI * v);
  }
  // Knuth for small lambda; normal approximation once it's large (and slow).
  function poisson(lambda: number): number {
    if (lambda <= 0) return 0;
    if (lambda < 25) {
      const L = Math.exp(-lambda);
      let k = 0;
      let p = 1;
      do {
        k++;
        p *= Math.random();
      } while (p > L);
      return k - 1;
    }
    return Math.max(0, Math.round(lambda + Math.sqrt(lambda) * gauss()));
  }

  // --- render the simulated frame ---------------------------------------
  let raf = 0;
  let imageData: ImageData | null = null;
  function scheduleRender() {
    if (raf) return;
    raf = requestAnimationFrame(() => {
      raf = 0;
      render();
    });
  }
  function render() {
    const ctx = canvasEl.getContext('2d');
    if (!ctx) return;
    if (!imageData) imageData = ctx.createImageData(W, H);
    const d = imageData.data;
    const t = exposure;
    // Display the per-pixel estimate n/(gain·t): constant mean brightness, with
    // relative noise that shrinks as exposure grows.
    const scale = 255 / (K * t);
    for (let i = 0; i < W * H; i++) {
      const j = i * 4;
      d[j] = clamp255(poisson(baseR[i] * K * t) * scale);
      d[j + 1] = clamp255(poisson(baseG[i] * K * t) * scale);
      d[j + 2] = clamp255(poisson(baseB[i] * K * t) * scale);
      d[j + 3] = 255;
    }
    ctx.putImageData(imageData, 0, 0);
  }
  const clamp255 = (v: number) => (v < 0 ? 0 : v > 255 ? 255 : v);

  // Re-render whenever exposure changes (once the scene is loaded).
  $effect(() => {
    exposure;
    if (ready && canvasEl) scheduleRender();
  });

  onMount(() => {
    const img = new Image();
    img.onload = () => {
      const off = document.createElement('canvas');
      off.width = W;
      off.height = H;
      const octx = off.getContext('2d');
      if (!octx) return;
      octx.drawImage(img, 0, 0, W, H);
      const px = octx.getImageData(0, 0, W, H).data;
      baseR = new Float32Array(W * H);
      baseG = new Float32Array(W * H);
      baseB = new Float32Array(W * H);
      baseLum = new Float32Array(W * H);
      for (let i = 0; i < W * H; i++) {
        const r = px[i * 4] / 255;
        const g = px[i * 4 + 1] / 255;
        const b = px[i * 4 + 2] / 255;
        baseR[i] = r;
        baseG[i] = g;
        baseB[i] = b;
        baseLum[i] = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      }
      // Highlight the flattest mid-tone patch near the centre.
      const region = pickRegion();
      hx = region.x;
      hy = region.y;
      hLum = region.lum;
      ready = true;
    };
    img.src = whitePine;
  });

  // Find the flattest mid-tone patch (lowest luminance variance) near the
  // centre, so the highlight really is a region of relatively similar
  // brightness that a single Poisson rate represents well.
  function pickRegion(): { x: number; y: number; lum: number } {
    let best = { x: W >> 1, y: H >> 1, lum: 0.5 };
    let bestVar = Infinity;
    const y0 = Math.floor(H * 0.3);
    const y1 = Math.floor(H * 0.7);
    const x0 = Math.floor(W * 0.3);
    const x1 = Math.floor(W * 0.7);
    for (let y = y0; y < y1; y += 2) {
      for (let x = x0; x < x1; x += 2) {
        let sum = 0;
        let sum2 = 0;
        let n = 0;
        for (let dy = -RWIN; dy <= RWIN; dy++) {
          for (let dx = -RWIN; dx <= RWIN; dx++) {
            const l = baseLum[(y + dy) * W + (x + dx)];
            sum += l;
            sum2 += l * l;
            n++;
          }
        }
        const mean = sum / n;
        if (mean < 0.2 || mean > 0.8) continue; // keep it a mid-tone patch
        const variance = sum2 / n - mean * mean;
        if (variance < bestVar) {
          bestVar = variance;
          best = { x, y, lum: mean };
        }
      }
    }
    return best;
  }

  // --- Poisson PMF for the highlighted region ---------------------------
  const lambdaHp = $derived(ready ? hLum * K * exposure : 0);

  // Plot geometry (SVG user units).
  const P = { w: 240, h: 132, padL: 10, padR: 10, padT: 10, padB: 26 };
  const plotW = P.w - P.padL - P.padR;
  const plotH = P.h - P.padT - P.padB;
  const plotBottom = P.h - P.padB;

  interface Chart {
    bars: { k: number; p: number }[];
    maxP: number;
    kmin: number;
    kmax: number;
    step: number;
    lambda: number;
    sigma: number;
    snr: number;
  }
  function buildChart(lam: number): Chart {
    const sigma = Math.sqrt(Math.max(lam, 1e-9));
    let kmax = Math.ceil(lam + 4 * sigma) + 1;
    if (kmax < 6) kmax = 6;
    const pmf = new Float64Array(kmax + 1);
    pmf[0] = Math.exp(-lam);
    for (let k = 1; k <= kmax; k++) pmf[k] = (pmf[k - 1] * lam) / k;
    const kmin = Math.max(0, Math.floor(lam - 4 * sigma));
    const step = Math.max(1, Math.ceil((kmax - kmin) / 40));
    const bars: { k: number; p: number }[] = [];
    let maxP = 0;
    for (let b = kmin; b <= kmax; b += step) {
      let p = 0;
      for (let k = b; k < b + step && k <= kmax; k++) p += pmf[k];
      bars.push({ k: b, p });
      if (p > maxP) maxP = p;
    }
    return { bars, maxP, kmin, kmax, step, lambda: lam, sigma, snr: sigma };
  }
  const chart = $derived(buildChart(lambdaHp));

  const xOf = (c: Chart, k: number) =>
    P.padL + ((k - c.kmin) / Math.max(1e-9, c.kmax - c.kmin)) * plotW;
  const yOf = (c: Chart, p: number) => P.padT + (1 - p / Math.max(1e-9, c.maxP)) * plotH;
  const barW = $derived(Math.max(1.4, (chart.step / Math.max(1e-9, chart.kmax - chart.kmin)) * plotW * 0.86));
</script>

<div class="wrap">
  <div class="stage">
    <div class="frame">
      <canvas bind:this={canvasEl} width={W} height={H} aria-label="Simulated exposure of the scene"></canvas>
      {#if ready}
        <span
          class="reticle"
          style="left:{((hx + 0.5) / W) * 100}%; top:{((hy + 0.5) / H) * 100}%; width:{((2 * RWIN + 1) / W) * 100}%; height:{((2 * RWIN + 1) / H) * 100}%"
        ></span>
      {/if}
    </div>
    <p class="region-label">highlighted region of relatively similar brightness</p>
  </div>

  <div class="panel">
    <svg class="chart" viewBox="0 0 {P.w} {P.h}" role="img" aria-label="Poisson distribution of the highlighted region's photon count">
      <line class="axis" x1={P.padL} y1={plotBottom} x2={P.w - P.padR} y2={plotBottom} />
      {#each chart.bars as bar (bar.k)}
        <rect
          class="bar"
          x={xOf(chart, bar.k) - barW / 2}
          y={yOf(chart, bar.p)}
          width={barW}
          height={Math.max(0, plotBottom - yOf(chart, bar.p))}
        />
      {/each}
      <!-- mean -->
      <line class="mean" x1={xOf(chart, chart.lambda)} y1={P.padT} x2={xOf(chart, chart.lambda)} y2={plotBottom} />
      <text class="axis-label" x={P.w / 2} y={P.h - 6}>photons collected</text>
    </svg>
  </div>

  <label class="control">
    <span>exposure time <em>{exposure}s</em></span>
    <input type="range" min="1" max={T_MAX} step="1" bind:value={exposure} />
  </label>
</div>

