/**
 * Discrete star field for the backdrop.
 *
 * Loads the quantized catalogue `stars-near.bin` from the gaia_mary project
 * (~601k stars; see [[gaia_mary reference]]) and renders it as an additive
 * THREE.Points cloud on a fixed celestial sphere. Positions in the file are
 * *ecliptic*-frame parsecs — the same frame the [[Skybox shader]] and the
 * [[Observer geometry]] camera use — so each star's direction lines up with the
 * textured Milky Way and co-rotates with it as the camera turns. No
 * relative-to-eye precision is needed here (we only keep directions, placed on
 * a sphere), so this is a much-simplified take on the source renderer.
 *
 * Binary format v2: 32-byte header (magic, version, count, posScale, mag range,
 * ci range) then 8-byte records (i16 x/y/z + u8 mag + u8 ci).
 */
import {
  AdditiveBlending,
  BufferGeometry,
  Float32BufferAttribute,
  Points,
  ShaderMaterial
} from 'three';

const STARS_BIN_MAGIC = 0x4e535441;
const STARS_BIN_VERSION = 2;

/** Radius of the celestial sphere the stars sit on (camera far is 10). */
const SPHERE_RADIUS = 4;

const VERT = /* glsl */ `
  attribute float aMag;
  attribute float aCI;
  uniform float uPixelRatio;
  uniform float uBaseSize;
  uniform float uRefMag;
  varying float vAlpha;
  varying vec3 vColor;

  vec3 ciColor(float ci) {
    vec3 cBlue  = vec3(0.55, 0.66, 1.00);
    vec3 cWhite = vec3(1.00, 0.97, 0.92);
    vec3 cWarm  = vec3(1.00, 0.62, 0.34);
    float t = clamp((ci + 0.4) / 2.4, 0.0, 1.0);
    return t < 0.5 ? mix(cBlue, cWhite, t * 2.0)
                   : mix(cWhite, cWarm, (t - 0.5) * 2.0);
  }

  void main() {
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);

    float flux = pow(10.0, -0.4 * (aMag - uRefMag));
    flux = clamp(flux, 0.0, 400.0);
    float s = uBaseSize * (0.7 + 1.7 * sqrt(flux));
    gl_PointSize = clamp(s * uPixelRatio, 0.0, 44.0);

    vAlpha = clamp(0.16 + 0.7 * sqrt(flux), 0.0, 1.0);

    vec3 sc = ciColor(aCI);
    float lum = dot(sc, vec3(0.2126, 0.7152, 0.0722));
    vColor = clamp(lum + (sc - lum) * 2.2, 0.0, 1.0);
  }
`;

const FRAG = /* glsl */ `
  precision mediump float;
  varying float vAlpha;
  varying vec3 vColor;
  uniform float uIntensity;

  void main() {
    vec2 uv = gl_PointCoord - 0.5;
    float d = length(uv);
    if (d > 0.5) discard;
    float core = smoothstep(0.5, 0.0, d);
    float glow = pow(core, 1.7);
    gl_FragColor = vec4(vColor * glow, vAlpha * glow * uIntensity);
  }
`;

export interface StarLayer {
  points: Points;
  dispose(): void;
}

export async function loadStars(url: string, intensity = 1.8): Promise<StarLayer> {
  const buf = await fetch(url).then((r) => {
    if (!r.ok) throw new Error(`stars: HTTP ${r.status} for ${url}`);
    return r.arrayBuffer();
  });

  const dv = new DataView(buf);
  if (dv.getUint32(0, true) !== STARS_BIN_MAGIC) throw new Error('stars: bad magic');
  if (dv.getUint32(4, true) !== STARS_BIN_VERSION) throw new Error('stars: bad version');
  const count = dv.getUint32(8, true);
  const magMin = dv.getFloat32(16, true);
  const magMax = dv.getFloat32(20, true);
  const ciMin = dv.getFloat32(24, true);
  const ciMax = dv.getFloat32(28, true);

  const i16 = new Int16Array(buf, 32, count * 4);
  const u8 = new Uint8Array(buf, 32, count * 8);
  const magK = magMax > magMin ? (magMax - magMin) / 255 : 0;
  const ciK = ciMax > ciMin ? (ciMax - ciMin) / 255 : 0;

  const positions = new Float32Array(count * 3);
  const mag = new Float32Array(count);
  const ci = new Float32Array(count);

  for (let i = 0; i < count; i++) {
    const o = i * 4;
    const x = i16[o];
    const y = i16[o + 1];
    const z = i16[o + 2];
    // Direction only — the posScale factor cancels under normalization.
    const len = Math.hypot(x, y, z) || 1;
    const k = SPHERE_RADIUS / len;
    positions[i * 3] = x * k;
    positions[i * 3 + 1] = y * k;
    positions[i * 3 + 2] = z * k;
    mag[i] = magMin + u8[i * 8 + 6] * magK;
    ci[i] = ciMin + u8[i * 8 + 7] * ciK;
  }

  const geom = new BufferGeometry();
  geom.setAttribute('position', new Float32BufferAttribute(positions, 3));
  geom.setAttribute('aMag', new Float32BufferAttribute(mag, 1));
  geom.setAttribute('aCI', new Float32BufferAttribute(ci, 1));

  const mat = new ShaderMaterial({
    uniforms: {
      uPixelRatio: { value: Math.min(window.devicePixelRatio || 1, 1.5) },
      uBaseSize: { value: 2.2 },
      uRefMag: { value: 5.5 },
      uIntensity: { value: intensity }
    },
    vertexShader: VERT,
    fragmentShader: FRAG,
    transparent: true,
    depthWrite: false,
    blending: AdditiveBlending
  });

  const points = new Points(geom, mat);
  points.frustumCulled = false;

  return {
    points,
    dispose() {
      geom.dispose();
      mat.dispose();
    }
  };
}
