<script lang="ts">
  import { onMount } from 'svelte';
  import type Reveal from 'reveal.js';
  import { initDeck } from './lib/reveal';
  import { deck, toggleMenu } from './lib/deck.svelte';
  import { slides } from './slides';
  import type { SlideMeta } from './lib/types';
  import Sky from './lib/components/Sky.svelte';
  import SlideMenu from './lib/components/SlideMenu.svelte';
  import MobileLinks from './lib/components/MobileLinks.svelte';
  import { isMobile } from './lib/device';

  // Phones can't render the slides + live sky well, so we serve the links page
  // (the part that matters there) and skip the whole deck. See lib/device.ts.
  const mobile = isMobile();

  let deckEl: HTMLDivElement;
  let api: Reveal | null = null;

  /** Map a slide's optional `background` into reveal `<section>` attributes. */
  function sectionAttrs(s: SlideMeta): Record<string, string | undefined> {
    const attrs: Record<string, string | undefined> = { id: s.id };
    if (s.transition) attrs['data-transition'] = s.transition;
    if (s.background) {
      if (/gradient/i.test(s.background)) attrs['data-background-gradient'] = s.background;
      else if (/^#|^rgb|^hsl/i.test(s.background)) attrs['data-background-color'] = s.background;
      else attrs['data-background-image'] = s.background;
    }
    return attrs;
  }

  const sync = () => {
    if (api) deck.index = api.getIndices().h;
  };

  const onKey = (e: KeyboardEvent) => {
    const t = e.target as HTMLElement | null;
    const typing =
      !!t && /^(input|textarea|select)$/i.test(t.tagName);
    if (!typing && (e.key === 'm' || e.key === 'M')) {
      toggleMenu();
    } else if (e.key === 'Escape' && deck.menuOpen) {
      deck.menuOpen = false;
    }
  };

  onMount(() => {
    if (mobile) return; // no deck on mobile — nothing to init or clean up
    let disposed = false;
    initDeck(deckEl).then((r) => {
      if (disposed) return;
      api = r;
      deck.api = r;
      deck.total = r.getTotalSlides();
      sync();
      r.on('slidechanged', sync);
      r.on('ready', sync);
    });
    window.addEventListener('keydown', onKey);
    return () => {
      disposed = true;
      api?.off('slidechanged', sync);
      api?.off('ready', sync);
      window.removeEventListener('keydown', onKey);
    };
  });
</script>

{#if mobile}
  <MobileLinks />
{:else}
  <Sky />
  <SlideMenu />

  <div class="reveal" bind:this={deckEl}>
    <div class="slides">
      {#each slides as s (s.id)}
        {@const SlideComponent = s.component}
        <section {...sectionAttrs(s)}>
          <SlideComponent />
        </section>
      {/each}
    </div>
  </div>
{/if}

<style>
  .reveal {
    position: absolute;
    inset: 0;
    z-index: 1;
  }
</style>
