-->
<script lang="ts">
  // Imported so Vite hashes them and resolves the Pages base path.
  import sub from '../../images/sub.webp';
  import stacked from '../../images/stacked.webp';

  let isStacked = $state(false);
</script>

<div class="wrap">
  <div class="stage">
    <img class="base" src={sub} alt="A single sub-exposure" />
    <img
      class="over"
      src={stacked}
      alt="The stacked result of many sub-exposures"
      style="opacity:{isStacked ? 1 : 0}"
      aria-hidden={!isStacked}
    />
  </div>

  <button class="stack-btn" class:on={isStacked} onclick={() => (isStacked = !isStacked)}>
    {isStacked ? '↺ Reset' : 'Stack!'}
  </button>
</div>

