import { Vector3 } from 'three';
import { OBLIQUITY_DEG } from './skybox';

/**
 * Geometry for "standing on Earth at latitude φ, facing due south."
 *
 * The skybox shader expects an *ecliptic*-frame direction. We build the
 * observer's zenith ("up") and look direction in the *equatorial* frame from
 * latitude + local sidereal time, then rotate into ecliptic so the shader maps
 * them onto the galactic Milky Way correctly.
 *
 * Diurnal motion is just the sidereal time θ advancing: the camera keeps
 * facing due south while the sky wheels about the north celestial pole. For a
 * southward view that reads as stars drifting east→west (left→right).
 */

const DEG = Math.PI / 180;
const EPS = OBLIQUITY_DEG * DEG;
const cosE = Math.cos(EPS);
const sinE = Math.sin(EPS);

/** Unit vector in the equatorial frame (+Z = north celestial pole). */
function equatorial(raRad: number, decRad: number): Vector3 {
  const cd = Math.cos(decRad);
  return new Vector3(cd * Math.cos(raRad), cd * Math.sin(raRad), Math.sin(decRad));
}

/** Equatorial → ecliptic: rotate by −obliquity about X. */
function eclipticFromEquatorial(v: Vector3): Vector3 {
  return new Vector3(v.x, cosE * v.y + sinE * v.z, -sinE * v.y + cosE * v.z);
}

export interface ObserverView {
  /** Local zenith direction, ecliptic frame (camera "up"). */
  up: Vector3;
  /** Look-at direction toward due south at `lookAltDeg`, ecliptic frame. */
  forward: Vector3;
}

/**
 * @param latitudeDeg  Observer latitude (≈40 for the talk's Northern view).
 * @param lstRad       Local sidereal time in radians (advance this to rotate).
 * @param lookAltDeg   Altitude above the southern horizon the camera centres
 *                     on; higher tilts the view up, dropping the horizon/
 *                     mountains toward the bottom of frame.
 */
export function observerView(
  latitudeDeg: number,
  lstRad: number,
  lookAltDeg: number
): ObserverView {
  const phi = latitudeDeg * DEG;
  // Both directions lie on the meridian (hour angle 0 ⇒ RA = LST).
  const zenithEq = equatorial(lstRad, phi);
  const lookDec = (latitudeDeg - 90 + lookAltDeg) * DEG;
  const lookEq = equatorial(lstRad, lookDec);
  return {
    up: eclipticFromEquatorial(zenithEq).normalize(),
    forward: eclipticFromEquatorial(lookEq).normalize()
  };
}
