import Reveal from 'reveal.js';
import RevealNotes from 'reveal.js/plugin/notes/notes.esm.js';
import type { RevealOptions } from 'reveal.js';

/**
 * reveal.js configuration for the deck. Slides are fixed at 1280×720 and
 * reveal scales them to fit any viewport (desktop or mobile). Hash routing
 * gives every slide a shareable deep link (e.g. `#/exposure`).
 */
const config: RevealOptions = {
  width: 1280,
  height: 720,
  margin: 0.06,
  minScale: 0.2,
  maxScale: 1.8,
  hash: true,
  respondToHashChanges: true,
  controls: true,
  controlsTutorial: false,
  controlsLayout: 'bottom-right',
  progress: true,
  slideNumber: 'c/t',
  center: true,
  transition: 'fade',
  transitionSpeed: 'default',
  backgroundTransition: 'none',
  overview: true,
  touch: true,
  keyboard: true,
  hideInactiveCursor: true,
  hideCursorTime: 4000,
  plugins: [RevealNotes]
};

/** Initialise reveal.js on the deck element and return the live instance. */
export async function initDeck(deckEl: HTMLElement): Promise<Reveal> {
  const r = new Reveal(deckEl, config);
  await r.initialize();
  return r;
}
