<!--
  Demo — a framed container for an interactive demo embedded in a slide.

  Provides consistent "interactive" chrome (label + live badge) and, crucially,
  stops pointer/touch/keyboard events from bubbling to reveal.js so dragging a
  slider or typing in a field never triggers slide navigation or a swipe.
-->
<script lang="ts">
  import type { Snippet } from 'svelte';

  interface Props {
    /** Short label for the demo (also its accessible name). */
    title?: string;
    /** Optional caption shown beneath the frame. */
    caption?: string;
    children?: Snippet;
  }

  let { title, caption, children }: Props = $props();

  // Svelte 5 dropped event modifiers; stop propagation explicitly so reveal's
  // document-level touch/keyboard handlers don't hijack interaction.
  const stop = (e: Event) => e.stopPropagation();
</script>

<!-- svelte-ignore a11y_no_noninteractive_element_interactions -->
<figure
  class="demo"
  role="group"
  aria-label={title ?? 'Interactive demo'}
  onkeydown={stop}
  onpointerdown={stop}
  ontouchstart={stop}
  ontouchmove={stop}
>
  {#if title}
    <figcaption class="demo-head">
      <span class="demo-title">{title}</span>
    </figcaption>
  {/if}
  <div class="demo-body">
    {@render children?.()}
  </div>
  {#if caption}
    <p class="demo-caption">{caption}</p>
  {/if}
</figure>

<style>
