<!--
  Sky — the live backdrop for the whole deck.

  A Three.js inverted-sphere Milky Way skybox (see lib/three/skybox.ts) viewed
  as if standing at ~40°N facing due south. The sky wheels slowly about the
  north celestial pole (diurnal motion); the galactic core starts front-and-
  centre. A solid-gray mountain silhouette anchors the horizon, and the entire
  stage is Gaussian-blurred so slide content stays legible on top.

  Honours prefers-reduced-motion by holding a single static frame.
-->
<script lang="ts">
  import { onMount } from 'svelte';
  import { PerspectiveCamera, Scene, WebGLRenderer, Color } from 'three';
  import { createSkybox } from '../three/skybox';
  import { loadStars, type StarLayer } from '../three/stars';
  import { observerView } from '../three/observer';

  // --- tunables (documented in vault: "Sky backdrop") ----------------------
  const LATITUDE_DEG = 40; // Northern-hemisphere view
  const LOOK_ALT_DEG = 30; // camera centre altitude above due south
  const START_LST_DEG = 266; // ≈ galactic core on the meridian at start
  const DEG_PER_SEC = 0.35; // diurnal drift rate (calm; not real-time)
  const FOV = 58;

  // Join an asset path onto Vite's base. Tolerant of a base with or without a
  // trailing slash — a missing slash here is what silently 404'd the skybox on
  // the deployed sub-path (see vault: "Deploy pipeline"). vite.config also
  // normalises the base; this is the belt-and-suspenders second guard.
  const asset = (p: string) => `${import.meta.env.BASE_URL.replace(/\/$/, '')}/${p}`;

  let stage: HTMLDivElement;
  let canvas: HTMLCanvasElement;
  let loaded = $state(false);

  onMount(() => {
    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const renderer = new WebGLRenderer({ canvas, antialias: false, powerPreference: 'low-power' });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
    renderer.setClearColor(new Color('#1d2021'), 1);

    const scene = new Scene();
    const camera = new PerspectiveCamera(FOV, 1, 0.01, 10);
    camera.position.set(0, 0, 0);

    let raf = 0;
    let disposed = false;
    let lstDeg = START_LST_DEG;
    let last = performance.now();
    let starLayer: StarLayer | null = null;

    function aim() {
      const { up, forward } = observerView(LATITUDE_DEG, lstDeg * (Math.PI / 180), LOOK_ALT_DEG);
      camera.up.copy(up);
      camera.lookAt(forward); // camera sits at origin, so a direction == a point
    }

    function size() {
      const w = stage.clientWidth || window.innerWidth;
      const h = stage.clientHeight || window.innerHeight;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
    }

    function frame(now: number) {
      const dt = (now - last) / 1000;
      last = now;
      if (!reduce) lstDeg = (lstDeg + DEG_PER_SEC * dt) % 360;
      aim();
      renderer.render(scene, camera);
      if (!disposed) raf = requestAnimationFrame(frame);
    }

    const onResize = () => size();
    window.addEventListener('resize', onResize);
    size();
    aim();

    createSkybox(asset('data/skybox.webp'))
      .then((sky) => {
        if (disposed) {
          sky.texture.dispose();
          return;
        }
        scene.add(sky.mesh);
        loaded = true;
        if (reduce) {
          renderer.render(scene, camera);
        } else {
          last = performance.now();
          raf = requestAnimationFrame(frame);
        }
      })
      .catch((err) => console.error('[Sky] skybox failed to load', err));

    // Discrete star catalogue on the same celestial sphere — co-rotates with
    // the skybox. Independent of the texture load; renders when ready.
    loadStars(asset('data/stars-near.bin'))
      .then((layer) => {
        if (disposed) {
          layer.dispose();
          return;
        }
        starLayer = layer;
        scene.add(layer.points);
        if (reduce) renderer.render(scene, camera);
      })
      .catch((err) => console.error('[Sky] stars failed to load', err));

    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', onResize);
      starLayer?.dispose();
      renderer.dispose();
    };
  });
</script>

<div class="sky" aria-hidden="true">
  <div class="sky-stage" bind:this={stage}>
    <canvas bind:this={canvas} class="sky-canvas" class:loaded></canvas>
    <!-- Solid-gray mountain horizon. preserveAspectRatio slices so the ridge
         keeps its shape across aspect ratios; anchored to the bottom. -->
    <svg class="mountains" viewBox="0 0 1600 360" preserveAspectRatio="xMidYMax slice">
      <path
        d="M0,360 L0,236 L86,196 L150,224 L223,150 L286,198 L360,116 L420,170
           L505,96 L560,150 L636,70 L705,140 L788,104 L860,178 L948,120
           L1020,182 L1098,128 L1170,196 L1255,138 L1330,200 L1420,150
           L1500,210 L1600,168 L1600,360 Z"
      />
    </svg>
  </div>
  <div class="sky-scrim"></div>
</div>

<style>
  .sky {
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    background: #1d2021;
  }

  /* The whole stage (sky + mountains) is Gaussian-blurred. A slight scale-up
     hides the soft, transparent edge the blur would otherwise reveal. */
  .sky-stage {
    position: absolute;
    inset: 0;
    filter: blur(7px);
    transform: scale(1.06);
    transform-origin: center;
  }

  .sky-canvas {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    display: block;
    opacity: 0;
    transition: opacity 1.4s ease;
  }
  .sky-canvas.loaded {
    opacity: 1;
  }

  .mountains {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    height: 34vh;
    display: block;
  }
  .mountains path {
    fill: #3a3735; /* solid gray ridge (gruvbox-leaning neutral) */
  }

  /* Crisp legibility wash sitting above the blurred stage. Darkens edges and
     the lower third so titles and body copy hold contrast over the band. */
  .sky-scrim {
    position: absolute;
    inset: 0;
    background:
      radial-gradient(120% 90% at 50% 38%, transparent 40%, rgba(29, 32, 33, 0.55) 100%),
      linear-gradient(to bottom, rgba(29, 32, 33, 0.35) 0%, transparent 26%),
      linear-gradient(to top, rgba(29, 32, 33, 0.78) 0%, transparent 34%);
  }

  @media (prefers-reduced-motion: reduce) {
    .sky-canvas {
      transition: none;
    }
  }
</style>
