<!--
  Slide — layout frame used *inside* a slide's content component. The reveal
  <section> itself is created by App.svelte from the slide registry; this just
  constrains width and handles vertical alignment, with an optional translucent
  panel for dense slides that need extra contrast over the sky.
-->
<script lang="ts">
  import type { Snippet } from 'svelte';

  interface Props {
    /** Vertical alignment of content within the slide. */
    align?: 'center' | 'start' | 'end';
    /** Max content width in px. */
    max?: number;
    /** Wrap content in a translucent gruvbox panel for legibility. */
    panel?: boolean;
    children?: Snippet;
  }

  let { align = 'center', max = 1080, panel = false, children }: Props = $props();
</script>

<div class="slide-inner" data-align={align} class:panel style="--slide-max:{max}px">
  {@render children?.()}
</div>

<style>
  .slide-inner {
    display: flex;
    flex-direction: column;
    height: 100%;
    max-width: var(--slide-max);
    margin: 0 auto;
  }
  .slide-inner[data-align='center'] {
    justify-content: center;
  }
  .slide-inner[data-align='start'] {
    justify-content: flex-start;
  }
  .slide-inner[data-align='end'] {
    justify-content: flex-end;
  }
  .slide-inner.panel {
    background: var(--panel);
    border: 1px solid var(--line-soft);
    border-radius: var(--radius);
    padding: 1.1em 1.3em;
    backdrop-filter: blur(2px);
  }
</style>
