import type Reveal from 'reveal.js';

/**
 * Shared, reactive deck state (Svelte 5 runes). Imported by the reveal host
 * (App.svelte) and the contents menu so navigation and the current-slide
 * indicator stay in sync.
 */
export const deck = $state<{
  api: Reveal | null;
  index: number;
  total: number;
  menuOpen: boolean;
}>({
  api: null,
  index: 0,
  total: 0,
  menuOpen: false
});

/** Jump to a top-level slide by its horizontal index and close the menu. */
export function goTo(index: number): void {
  deck.api?.slide(index);
  deck.menuOpen = false;
}

export function toggleMenu(): void {
  deck.menuOpen = !deck.menuOpen;
}
