import { mount } from 'svelte';

// Self-hosted fonts (no CDN) so a live talk never depends on the network.
import '@fontsource-variable/fraunces';
import '@fontsource/spectral/400.css';
import '@fontsource/spectral/500.css';
import '@fontsource/spectral/600.css';
import '@fontsource/ibm-plex-mono/400.css';
import '@fontsource/ibm-plex-mono/500.css';

// reveal.js core layout/transition CSS — our theme lives in app.css and
// deliberately overrides reveal's bundled themes (which we do not import).
import 'reveal.js/dist/reveal.css';

import './app.css';
import App from './App.svelte';

const target = document.getElementById('app');
if (!target) throw new Error('#app mount target not found');

const app = mount(App, { target });

export default app;
