/**
 * Inverted-sphere Milky Way skybox.
 *
 * Adapted from the `gaia_mary` project (src/lib/starmap/skybox.ts + vault note
 * "Skybox rotation fix"). An inverted unit sphere is locked to the camera and
 * samples a galactic-frame equirect WebP directly in the fragment shader,
 * mapping a scene-world *ecliptic* direction through
 *   ecliptic → equatorial (+obliquity about X)
 *   equatorial → galactic (IAU/Hipparcos J2000)
 *   galactic → cube-atlas axes
 *   equirect UV
 * We sample the equirect ourselves rather than using `scene.background`
 * because Three's EquirectangularReflectionMapping round-trips through a cube
 * map and shifts the bulge a few degrees off Sgr A*.
 *
 * Our scene aims the camera using equatorial directions converted to ecliptic
 * (see Sky.svelte), so the obliquity term here cancels on the camera side and
 * the Milky Way lands in the correct galactic orientation.
 */
import {
  BackSide,
  Mesh,
  ShaderMaterial,
  SphereGeometry,
  SRGBColorSpace,
  TextureLoader
} from 'three';
import type { Texture } from 'three';

export const OBLIQUITY_DEG = 23.4392811;

const VERT = /* glsl */ `
  varying vec3 vDir;
  void main() {
    vDir = normalize(position);
    mat4 mvNoTrans = modelViewMatrix;
    mvNoTrans[3].xyz = vec3(0.0);
    gl_Position = projectionMatrix * mvNoTrans * vec4(position, 1.0);
    gl_Position.z = gl_Position.w; // force depth to the far plane
  }
`;

const FRAG = /* glsl */ `
  precision highp float;
  uniform sampler2D tEquirect;
  uniform float uIntensity;
  uniform float uCe;
  uniform float uSe;
  varying vec3 vDir;

  void main() {
    vec3 dEcl = normalize(vDir);

    // Ecliptic -> equatorial (+obliquity about X).
    vec3 dEq = vec3(
      dEcl.x,
      uCe * dEcl.y - uSe * dEcl.z,
      uSe * dEcl.y + uCe * dEcl.z
    );

    // Equatorial -> galactic (IAU/Hipparcos, J2000). Row-major dots.
    vec3 r0 = vec3(-0.0548755604162154, -0.8734370902348850, -0.4838350155487132);
    vec3 r1 = vec3( 0.4941094278755837, -0.4448296299600112,  0.7469822444972189);
    vec3 r2 = vec3(-0.8676661490190047, -0.1980763734312015,  0.4559837761750669);
    vec3 dGal = vec3(dot(r0, dEq), dot(r1, dEq), dot(r2, dEq));

    // Galactic -> cube atlas axes.
    vec3 dCube = vec3(dGal.y, dGal.z, -dGal.x);

    vec3 dn = normalize(dCube);
    vec2 uv = vec2(
      atan(dn.z, dn.x) * 0.15915494309189535 + 0.5,
      asin(clamp(dn.y, -1.0, 1.0)) * 0.3183098861837907 + 0.5
    );
    vec4 c = texture2D(tEquirect, uv);
    gl_FragColor = vec4(c.rgb * uIntensity, 1.0);
  }
`;

export interface Skybox {
  mesh: Mesh;
  texture: Texture;
  setIntensity(v: number): void;
}

export async function createSkybox(textureUrl: string, intensity = 0.42): Promise<Skybox> {
  const tex = await new TextureLoader().loadAsync(textureUrl);
  tex.colorSpace = SRGBColorSpace;
  tex.generateMipmaps = false;

  const eps = (OBLIQUITY_DEG * Math.PI) / 180;
  const mat = new ShaderMaterial({
    side: BackSide,
    depthWrite: false,
    depthTest: false,
    uniforms: {
      tEquirect: { value: tex },
      uIntensity: { value: intensity },
      uCe: { value: Math.cos(eps) },
      uSe: { value: Math.sin(eps) }
    },
    vertexShader: VERT,
    fragmentShader: FRAG
  });

  const mesh = new Mesh(new SphereGeometry(1, 64, 32), mat);
  mesh.frustumCulled = false;
  mesh.renderOrder = -1000;

  return {
    mesh,
    texture: tex,
    setIntensity(v: number) {
      mat.uniforms.uIntensity.value = v;
    }
  };
}
