<!--
  SnrVectors — a looping vector-addition animation for how independent
  sub-exposures combine "in quadrature". One unit vector points up; a second,
  orthogonal unit vector fades in head-to-tail; their resultant (length
  √(1²+1²)) fades in; the two legs fade out; the resultant rotates back to
  vertical and rescales to unit — becoming the original arrow, so the loop is
  seamless. The √N growth itself is carried by the expression on the slide.

  Non-interactive, so it is NOT wrapped in <Demo>. The rAF loop only runs while
  the slide is on-screen (reveal keeps every slide in the DOM), and freezes for
  prefers-reduced-motion.
-->
<script lang="ts">
  import { onMount } from 'svelte';

  // Geometry (SVG user units). Origin sits low-left; L is one unit vector.
  const Ox = 64;
  const Oy = 196;
  const L = 92;
  const DUR = 5; // seconds per loop

  const reduced =
    typeof matchMedia !== 'undefined' && matchMedia('(prefers-reduced-motion: reduce)').matches;

  let phase = $state(reduced ? 0.46 : 0); // a frozen frame shows all three arrows
  let rootEl: HTMLDivElement;

  const lerp = (a: number, b: number, u: number) => a + (b - a) * u;

  interface Frame {
    ax: number;
    ay: number;
    bx: number;
    by: number;
    cx: number;
    cy: number;
    aOp: number;
    bOp: number;
    cOp: number;
  }
  function frame(t: number): Frame {
    const ax = Ox; // tip of the first (vertical) unit vector
    const ay = Oy - L;
    const bx = Ox + L; // tip of the orthogonal second vector
    const by = Oy - L;

    const aOp = t < 0.54 ? 1 : t < 0.7 ? 1 - (t - 0.54) / 0.16 : 0;
    const bOp =
      t < 0.18 ? 0 : t < 0.36 ? (t - 0.18) / 0.18 : t < 0.54 ? 1 : t < 0.7 ? 1 - (t - 0.54) / 0.16 : 0;
    const cOp = t < 0.36 ? 0 : t < 0.54 ? (t - 0.36) / 0.18 : 1;

    // resultant: fixed at 45°/√2 until the legs are gone, then rotate to
    // vertical and rescale to unit so it lands exactly on the first vector.
    let cx = bx;
    let cy = by;
    if (t >= 0.7) {
      const s = (t - 0.7) / 0.3;
      const ang = lerp(Math.PI / 4, Math.PI / 2, s);
      const len = lerp(Math.SQRT2, 1, s) * L;
      cx = Ox + len * Math.cos(ang);
      cy = Oy - len * Math.sin(ang);
    }
    return { ax, ay, bx, by, cx, cy, aOp, bOp, cOp };
  }
  const f = $derived(frame(phase));

  onMount(() => {
    let raf = 0;
    let last = 0;
    let running = false;
    const tick = (ts: number) => {
      if (!running) return;
      if (!last) last = ts;
      phase = (phase + (ts - last) / 1000 / DUR) % 1;
      last = ts;
      raf = requestAnimationFrame(tick);
    };
    const start = () => {
      if (running || reduced) return;
      running = true;
      last = 0;
      raf = requestAnimationFrame(tick);
    };
    const stop = () => {
      running = false;
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    };
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) e.isIntersecting ? start() : stop();
      },
      { threshold: 0.2 }
    );
    io.observe(rootEl);
    return () => {
      stop();
      io.disconnect();
    };
  });
</script>

<div class="viz" bind:this={rootEl}>
  <svg viewBox="0 0 240 240" role="img" aria-label="Two orthogonal unit vectors add to a resultant of length root two, which rotates back to vertical — independent noise adds in quadrature.">
    <defs>
      <marker id="ah-comp" viewBox="0 0 10 10" refX="8" refY="5" markerUnits="userSpaceOnUse" markerWidth="13" markerHeight="13" orient="auto-start-reverse">
        <path d="M0 0 L10 5 L0 10 z" class="mk-comp" />
      </marker>
      <marker id="ah-sum" viewBox="0 0 10 10" refX="8" refY="5" markerUnits="userSpaceOnUse" markerWidth="14" markerHeight="14" orient="auto-start-reverse">
        <path d="M0 0 L10 5 L0 10 z" class="mk-sum" />
      </marker>
    </defs>

    <!-- right-angle marker, visible while both legs are -->
    <path
      class="rangle"
      d="M{Ox + 11} {Oy - L} L{Ox + 11} {Oy - L + 11} L{Ox} {Oy - L + 11}"
      style="opacity:{Math.min(f.aOp, f.bOp)}"
    />

    <!-- first (vertical) unit vector -->
    <line class="vec comp" x1={Ox} y1={Oy} x2={f.ax} y2={f.ay} style="opacity:{f.aOp}" marker-end="url(#ah-comp)" />
    <!-- orthogonal second vector, head-to-tail -->
    <line class="vec comp" x1={f.ax} y1={f.ay} x2={f.bx} y2={f.by} style="opacity:{f.bOp}" marker-end="url(#ah-comp)" />
    <!-- resultant -->
    <line class="vec sum" x1={Ox} y1={Oy} x2={f.cx} y2={f.cy} style="opacity:{f.cOp}" marker-end="url(#ah-sum)" />

    <circle class="origin" cx={Ox} cy={Oy} r="2.6" />
  </svg>
</div>

<style>
  .viz {
    width: 100%;
    display: flex;
    justify-content: center;
  }
  svg {
    width: 100%;
    max-width: 320px;
    height: auto;
    display: block;
  }
  .vec {
    fill: none;
    stroke-width: 3;
    stroke-linecap: round;
  }
  .comp {
    stroke: var(--aqua);
  }
  .sum {
    stroke: var(--accent);
  }
  .mk-comp {
    fill: var(--aqua);
  }
  .mk-sum {
    fill: var(--accent);
  }
  .rangle {
    fill: none;
    stroke: var(--aqua);
    stroke-width: 1.4;
  }
  .origin {
    fill: var(--fg-dim);
  }
</style>
