/**
 * Mobile detection for the deck. The reveal.js slides + live Three.js sky don't
 * render well on phones, so on mobile we skip the deck entirely and show the
 * `MobileLinks` page instead (the links are what matters there).
 *
 * Heuristic: a user-agent sniff, plus a coarse-pointer + small-viewport
 * fallback, plus the iPadOS-reports-as-desktop special case. Two URL overrides:
 * `?slides` forces the full deck (open the talk on a phone deliberately) and
 * `?mobile` forces the links page (preview it from a desktop). Both also work
 * as `#slides` / `#mobile` hash flags.
 */
function hasFlag(name: string): boolean {
  if (typeof window === 'undefined') return false;
  const re = new RegExp(`\\b${name}\\b`);
  return re.test(window.location.search) || re.test(window.location.hash);
}

export function forcesDeck(): boolean {
  return hasFlag('slides');
}

export function isMobile(): boolean {
  if (typeof navigator === 'undefined' || typeof window === 'undefined') return false;
  if (forcesDeck()) return false;
  if (hasFlag('mobile')) return true;

  const ua = navigator.userAgent || '';
  const uaMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile/i.test(ua);

  // iPadOS 13+ reports as desktop Safari — catch it via Mac + touch points.
  const iPadOS = navigator.platform === 'MacIntel' && (navigator.maxTouchPoints ?? 0) > 1;

  const coarseSmall =
    window.matchMedia?.('(pointer: coarse) and (max-width: 820px)').matches ?? false;

  return uaMobile || iPadOS || coarseSmall;
}
